+// ADR-001: un movimiento no se edita ni se borra; se corrige con un movimiento inverso al final de la lista.
+// El efecto sobre el stock es el mismo que si el movimiento no se hubiera hecho. Aplica RF-002 (puede lanzar).
+export function corregirMovimiento(movimientos, indice) {
+  if (!Number.isInteger(indice) || indice < 0 || indice >= movimientos.length)
+    throw new RangeError(`Índice de movimiento inválido: ${indice}`);
+  const { tipo, articulo, almacen, cantidad } = movimientos[indice];
+  return registrarMovimiento(movimientos, { tipo: tipo === "ingreso" ? "egreso" : "ingreso", articulo, almacen, cantidad });
+}
